import collections
# connected components
def comps(cells):
    cs=set(cells); seen=set(); out=[]
    for x in cells:
        if x in seen: continue
        st=[x]; comp=set()
        while st:
            y=st.pop()
            if y in comp: continue
            comp.add(y); seen.add(y)
            r,c=y
            for dr in(-1,0,1):
                for dc in(-1,0,1):
                    n=(r+dr,c+dc)
                    if n in cs and n not in comp: st.append(n)
        out.append(sorted(comp))
    return out
for comp in comps(cells):
    rs=[r for r,c in comp];cs=[c for r,c in comp]
